static void onDialog(const QString &name,std::function<void(QDialog*)> callback){auto *timer=new QTimer(qApp);QObject::connect(timer,&QTimer::timeout,timer,[=]{for(auto *top:QApplication::topLevelWidgets())if(auto *d=qobject_cast<QDialog*>(top);d&&d->isVisible()&&d->objectName()==name){timer->stop();timer->deleteLater();callback(d);return;}});timer->start(20);}
static QAction *action(QWidget *parent,const char *zh,const char *en){for(auto *a:parent->findChildren<QAction*>())if(a->text()==words(zh,en))return a;return nullptr;}
static void answerInput(const QString &answer){onDialog("researchWorkspaceInputDialog",[=](QDialog *d){d->findChild<QLineEdit*>("researchWorkspaceInput")->setText(answer);d->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Ok)->click();});}
static void acceptConfirm(){onDialog("researchWorkspaceConfirmDialog",[](QDialog *d){d->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Ok)->click();});}
static void contextChoice(QListWidget *list,const QString &caption){auto *timer=new QTimer(qApp);QObject::connect(timer,&QTimer::timeout,timer,[=]{if(auto *menu=qobject_cast<QMenu*>(QApplication::activePopupWidget())){for(auto *a:menu->actions())if(a->text()==caption){timer->stop();timer->deleteLater();menu->setActiveAction(a);key(menu,Qt::Key_Return);return;}}});timer->start(20);list->customContextMenuRequested(list->visualItemRect(list->currentItem()).center());}
int main(int argc,char **argv){const auto report=argument(1);argc=1;TWApp app(argc,argv);app.setQuitOnLastWindowClosed(false);QTimer::singleShot(60,&app,[&]{QJsonArray checks;int failures=0;auto check=[&](const QString &name,bool pass){checks.append(QJsonObject{{"name",name},{"passed",pass}});failures+=!pass;put(report,QJsonDocument(QJsonObject{{"checks",checks},{"failures",failures},{"devicePixelRatio",qApp->primaryScreen()->devicePixelRatio()}}).toJson());};const auto folder=QFileInfo(report).absolutePath(),repo=folder+"/author",peer=folder+"/coauthor",remote=folder+"/shared.git";QDir().mkpath(repo);QDir().mkpath(peer);
auto git=[&](const QString &cwd,const QStringList &args){QProcess p;p.setWorkingDirectory(cwd);p.setProgram(systemTool("git"));p.setArguments(args);auto env=QProcessEnvironment::systemEnvironment();env.insert("GIT_CONFIG_GLOBAL",folder+"/private-config");env.insert("GIT_CONFIG_NOSYSTEM","1");p.setProcessEnvironment(env);p.setCreateProcessArgumentsModifier([](QProcess::CreateProcessArguments *a){a->flags|=0x08000000;});p.start();p.waitForFinished(15000);return qMakePair(p.exitCode(),p.readAllStandardOutput());};
check("private author repository initialized",git(repo,{"init","-b","main"}).first==0);git(repo,{"config","user.name","Author"});git(repo,{"config","user.email","author@example.invalid"});put(repo+"/main.tex","\\documentclass{article}\n\\begin{document}Research\\end{document}\n");put(repo+"/notes.tex","A shared statement.\n");git(repo,{"add","."});check("initial author commit",git(repo,{"commit","-m","Start"}).first==0);
Tw::Settings().setValue("openPDFwithTeX",false);auto *w=new TeXDocumentWindow(repo+"/main.tex");w->resize(1000,740);w->show();settle();openVersionControl(w);auto *d=w->findChild<QDialog*>("researchVersionDialog");auto *list=d->findChild<QListWidget*>("researchGitFiles");auto ready=[&]{return list->isEnabled();};check("Git dialog ready",waitFor(ready));
auto refresh=[&]{action(d,"刷新","Refresh")->trigger();return waitFor(ready);};auto chooseFile=[&](const QString &file,bool staged){for(int n=0;n<list->count();++n)if(list->item(n)->text().endsWith(file)&&list->item(n)->data(Qt::UserRole+1).toBool()==staged){list->setCurrentRow(n);return waitFor(ready);}return false;};
put(repo+"/中文 notes.tex","New reference notes\n");refresh();check("Unicode untracked file discovered",chooseFile("中文 notes.tex",false));if(list->currentItem())list->currentItem()->setCheckState(Qt::Checked);check("checkbox stages a Unicode file",waitFor(ready)&&git(repo,{"diff","--cached","--name-only","-z"}).second.contains(QString("中文 notes.tex").toUtf8()));chooseFile("中文 notes.tex",true);if(list->currentItem())list->currentItem()->setCheckState(Qt::Unchecked);check("checkbox unstages without discarding content",waitFor(ready)&&git(repo,{"diff","--cached","--name-only","-z"}).second.isEmpty()&&bytes(repo+"/中文 notes.tex")=="New reference notes\n");
answerInput("Working notes");action(d,"暂存工作进度…","Stash work…")->trigger();check("stash includes untracked files",waitFor(ready)&&!QFileInfo::exists(repo+"/中文 notes.tex")&&git(repo,{"stash","list"}).second.contains("Working notes"));onDialog("researchGitPicker",[](QDialog *dlg){dlg->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Ok)->click();});onDialog("researchGitStashPreview",[](QDialog *dlg){dlg->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Ok)->click();});action(d,"恢复暂存进度…","Apply stash…")->trigger();check("stash apply restores untracked content",waitFor([&]{return ready()&&QFileInfo::exists(repo+"/中文 notes.tex");})&&bytes(repo+"/中文 notes.tex")=="New reference notes\n");QFile::remove(repo+"/中文 notes.tex");refresh();
answerInput("revision");action(d,"新建分支…","New branch…")->trigger();check("new branch UI switches to created branch",waitFor(ready)&&git(repo,{"branch","--show-current"}).second.trimmed()=="revision");auto *tabs=d->findChild<QTabBar*>();tabs->setCurrentIndex(2);check("branches tab loads",waitFor(ready)&&list->count()==2);for(int n=0;n<list->count();++n)if(list->item(n)->text()=="main")list->setCurrentRow(n);contextChoice(list,words("切换到此分支","Switch branch"));check("switch branch keeps author files",waitFor(ready)&&git(repo,{"branch","--show-current"}).second.trimmed()=="main");tabs->setCurrentIndex(0);waitFor(ready);
check("local bare collaboration remote created",git(folder,{"init","--bare",remote}).first==0);git(repo,{"remote","add","origin",remote});
auto remoteDialog=[&]{onDialog("researchGitRemote",[](QDialog *dlg){dlg->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Ok)->click();});};remoteDialog();action(d,"推送版本…","Push…")->trigger();check("first push sets tracking branch",waitFor([&]{return ready()&&git(repo,{"rev-parse","--abbrev-ref","@{upstream}"}).second.trimmed()=="origin/main";}));
check("second author clones shared repository",git(folder,{"clone","-b","main",remote,peer}).first==0);git(peer,{"config","user.name","Coauthor"});git(peer,{"config","user.email","coauthor@example.invalid"});put(peer+"/notes.tex","Coauthor revision.\n");git(peer,{"add","notes.tex"});git(peer,{"commit","-m","Coauthor edit"});git(peer,{"push"});put(repo+"/notes.tex","Author revision.\n");git(repo,{"add","notes.tex"});git(repo,{"commit","-m","Author edit"});refresh();
remoteDialog();action(d,"推送版本…","Push…")->trigger();check("non-fast-forward push is rejected without rewriting history",waitFor(ready)&&git(repo,{"log","-1","--format=%s"}).second.trimmed()=="Author edit"&&git(peer,{"log","-1","--format=%s"}).second.trimmed()=="Coauthor edit");
remoteDialog();action(d,"拉取并合并…","Pull and merge…")->trigger();check("divergent pull exposes a conflict in the same dialog",waitFor([&]{return ready()&&list->count()==1&&list->item(0)->text().startsWith(words("冲突","Conflict"));}));if(list->count()){list->setCurrentRow(0);waitFor(ready);onDialog("researchGitConflict",[&](QDialog *conflict){auto *reference=conflict->findChild<QTabWidget*>();check("conflict editor contains base, current and incoming texts",reference&&reference->count()==3&&qobject_cast<QPlainTextEdit*>(reference->widget(0))->toPlainText().contains("shared statement")&&qobject_cast<QPlainTextEdit*>(reference->widget(1))->toPlainText().contains("Author revision")&&qobject_cast<QPlainTextEdit*>(reference->widget(2))->toPlainText().contains("Coauthor revision"));conflict->grab().save(folder+"/conflict-three-way.png");auto *edit=conflict->findChild<QPlainTextEdit*>("researchGitMergedText");const auto original=edit->toPlainText();auto cursor=edit->textCursor();cursor.setPosition(0);edit->setTextCursor(cursor);action(conflict,"此处保留双方内容","Keep both here")->trigger();check("per-conflict keep-both removes markers and retains both paragraphs",!edit->toPlainText().contains("<<<<<<<")&&edit->toPlainText().contains("Author revision")&&edit->toPlainText().contains("Coauthor revision"));edit->undo();check("conflict choice is one undo step",edit->toPlainText()==original);edit->redo();edit->setPlainText("A statement agreed by both authors.\n");conflict->findChild<QDialogButtonBox*>()->button(QDialogButtonBox::Ok)->click();});contextChoice(list,words("解决冲突…","Resolve conflict…"));check("conflict result is saved and staged",waitFor([&]{return ready()&&git(repo,{"diff","--name-only","--diff-filter=U"}).second.isEmpty();})&&bytes(repo+"/notes.tex")=="A statement agreed by both authors.\n");}
d->findChild<QLineEdit*>("researchGitMessage")->setText("Agree on statement");d->findChild<QPushButton*>("researchGitCommit")->click();check("merge commit completes via normal commit button",waitFor([&]{return ready()&&list->count()==0;})&&git(repo,{"rev-list","--parents","-n","1","HEAD"}).second.trimmed().split(' ').size()==3);
remoteDialog();action(d,"推送版本…","Push…")->trigger();check("resolved collaboration result reaches shared remote",waitFor(ready)&&git(peer,{"pull","--ff-only"}).first==0&&bytes(peer+"/notes.tex")==bytes(repo+"/notes.tex"));
put(repo+"/notes.tex","Unsaved working variation\n");refresh();chooseFile("notes.tex",false);acceptConfirm();contextChoice(list,words("恢复工作区文件…","Restore working file…"));check("restore working file keeps a recovery copy",waitFor([&]{return ready()&&bytes(repo+"/notes.tex")=="A statement agreed by both authors.\n";})&&!QDir(repo+"/.git/texline-recovery").entryList(QDir::Files).isEmpty());
key(d,Qt::Key_Escape);settle();check("Git Esc restores editor focus",w->editor()->hasFocus());for(auto *window:TeXDocumentWindow::documentList())window->textDoc()->setModified(false);for(auto *window:TeXDocumentWindow::documentList())window->close();settle();app.exit(failures?1:0);
});return app.exec();}
